# ==========================================
# JOGADOR (HERÓI)
# ==========================================
ENTITY player
# TRANSFORM: posX posY posZ [yaw] - Posição inicial e rotação opcional (yaw em radianos, pode usar "PI")
TRANSFORM 0.0 0.0 0.0
# PHYSICS: velX velY velZ drag - Velocidade inicial e coeficiente de arrasto (0.0-1.0)
PHYSICS 0.0 0.0 0.0 0.90
# COLLISION: minX minY minZ maxX maxY maxZ isStatic isTrigger - Bounding box e flags
COLLISION -7.0 0.0 -7.0 7.0 30.0 3.0 0 0
PLAYER_CONTROL
# HUD: maxHealth heatSpeed coolSpeed - Configurações do HUD do cockpit
HUD 100.0 2.0 10.0
# HEALTH: maxHP - Pontos de vida máximos
HEALTH 1000.0
# WEAPON_CONTROL: aimMode - Modo de mira (1=Camera, 0=Physical)
WEAPON_CONTROL 1

# --- ARMAS DO JOGADOR ---

# Laser Esquerdo (Braço)
ENTITY p_laser_L
TRANSFORM 0 0 0
# WEAPON: type rate speed damage range heat burstTotal burstRate
#   type: WEAPON_PULSE_LASER ou WEAPON_MISSILE_LAUNCHER
#   rate: Tempo entre disparos (segundos)
#   speed: Velocidade do projétil
#   damage: Dano por projétil
#   range: Alcance máximo
#   heat: Calor gerado por disparo
#   burstTotal: Quantidade de tiros no burst
#   burstRate: Tempo entre tiros do burst
WEAPON WEAPON_PULSE_LASER 0.8 250.0 5.0 500.0 2.0 2 0.1
# ATTACHMENT: parentName offsetX offsetY offsetZ - Offset relativo ao parent (espaço local)
ATTACHMENT player -1.5 17.0 1.5

# Laser Direito (Braço)
ENTITY p_laser_R
TRANSFORM 0 0 0
WEAPON WEAPON_PULSE_LASER 0.8 250.0 5.0 500.0 2.0 2 0.1
ATTACHMENT player 1.5 17.0 1.5

# Missil Esquerdo (Ombro)
ENTITY p_missile_L
TRANSFORM 0 0 0
WEAPON WEAPON_MISSILE_LAUNCHER 5.0 60.0 2.5 1000.0 5.0 20 0.115
ATTACHMENT player -1.5 21.0 1.5

# Missil Direito (Ombro)
ENTITY p_missile_R
TRANSFORM 0 0 0
WEAPON WEAPON_MISSILE_LAUNCHER 5.0 60.0 2.5 1000.0 5.0 20 0.115
ATTACHMENT player 1.5 21.0 1.5

# LINK_WEAPON: owner slot weaponId group isActive - Vincula arma ao mecha
#   owner: Nome da entidade dona da arma
#   slot: Slot da arma (0-3)
#   weaponId: Nome da entidade da arma
#   group: Grupo de armas (0-1)
#   isActive: Se o grupo está ativo (1) ou não (0)
LINK_WEAPON player 0 p_laser_L 0 1
LINK_WEAPON player 1 p_laser_R 0 1
LINK_WEAPON player 2 p_missile_L 1 0
LINK_WEAPON player 3 p_missile_R 1 0



# ==========================================
# BOSS: HEAVY MECHA (Render ID 13)
# ==========================================
ENTITY boss_unit
# Position: 400m ahead
TRANSFORM 0.0 0.0 -350.0 0.0
PHYSICS 0.0 0.0 0.0 0.90
# Massive Collision (20x65x20)
COLLISION -20.0 0.0 -20.0 20.0 65.0 20.0 0 1
HEALTH 5000.0
# RENDER 13 = MODEL_ID_ENEMY_BOSS
RENDER 13 255 200 200 255
# AI: Vision 800m, Attack 600m
AI_CONTROL 800.0 150.0

# --- BOSS WEAPONS ---

ENTITY boss_gun_L
TRANSFORM 0 0 0
# Damage 25, Range 900
WEAPON WEAPON_PULSE_LASER 0.8 250.0 5.0 500.0 5.0 3 0.15
# Z Offset increased to 35.0 to clear hitbox
ATTACHMENT boss_unit -18.5 36.0 13.0
LINK_WEAPON boss_unit 0 boss_gun_L 0 1

ENTITY boss_gun_R
TRANSFORM 0 0 0
WEAPON WEAPON_PULSE_LASER 0.8 250.0 5.0 500.0 5.0 3 0.15
# Z Offset increased to 35.0 to clear hitbox
ATTACHMENT boss_unit 18.5 36.0 13.0
LINK_WEAPON boss_unit 1 boss_gun_R 0 1
